<?php declare(strict_types=1); namespace App\Interface\Http\Arena; use App\Application\Arena\DTO\Request\CreateDuelRequestDto; use App\Application\Arena\DTO\Request\SubjectsDuelRequestDto; use Psr\Http\Message\ServerRequestInterface; final class ArenaRequestFactory { private function body(ServerRequestInterface $r):array{try{$v=json_decode((string)$r->getBody(),true,512,JSON_THROW_ON_ERROR);if(!is_array($v))throw new \InvalidArgumentException();return$v;}catch(\Throwable){throw new \InvalidArgumentException('JSON inválido.');}} public function create(ServerRequestInterface $r):CreateDuelRequestDto{$v=$this->body($r);return new CreateDuelRequestDto((int)($v['max_players']??0),(int)($v['subjects_per_player']??0),(int)($v['question_count']??0),(int)($v['question_seconds']??0),(string)($v['visibility']??'PRIVATE'));} public function code(ServerRequestInterface $r):string{$v=$this->body($r);$x=$v['code']??null;if(!is_string($x)||trim($x)==='')throw new \InvalidArgumentException('Código inválido.');return strtoupper(trim($x));} public function subjects(ServerRequestInterface $r):SubjectsDuelRequestDto{$v=$this->body($r);$ids=$v['taxonomy_subject_ids']??null;if(!is_array($ids)||array_filter($ids,fn($id)=>!is_string($id)||$id===''))throw new \InvalidArgumentException('Assuntos inválidos.');return new SubjectsDuelRequestDto(array_values(array_unique($ids)));} }
